alter table public.schools add column if not exists timezone text not null default 'America/Port_of_Spain';
alter table public.schools add column if not exists is_test_data boolean not null default false;
alter table public.classes add column if not exists is_test_data boolean not null default false;
create table if not exists public.school_staff (
 id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools(id) on delete cascade,
 full_name text not null, role text not null check (role in ('teacher','principal')), email text not null,
 is_test_data boolean not null default false, created_at timestamptz not null default now()
);
alter table public.classes add column if not exists assigned_staff_id uuid references public.school_staff(id) on delete set null;
insert into public.schools (name,timezone,is_test_data) values ('Fyzabad Presbyterian Primary','America/Port_of_Spain',true) on conflict do nothing;
